def bst_search(node, target=42):
    # 基准：空树或已找到
    if node is None or node.key == target:
        return node

    # 方向性淘汰：target 小于当前节点，整个右子树被排除
    if target < node.key:
        return bst_search(node.left, target)
    # target 大于当前节点，整个左子树被排除
    else:
        return bst_search(node.right, target)
